contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, uint minsum) public payable {
        require(address(this).balance >= amount);

        // Fresh contract: configure MinSum, then deposit to build a balance.
        c.SetMinSum(minsum);
        c.Deposit{value: amount}();
        c.Initialized();

        uint balBefore = c.balances(address(this));
        uint etherBefore = address(c).balance;

        // Decide rule branch via the observable balance vs MinSum.
        bool reverted;
        try c.Collect(0) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (balBefore >= c.MinSum()) {
            assert(!reverted && c.balances(address(this)) == balBefore && address(c).balance == etherBefore);
        } else {
            assert(!reverted && c.balances(address(this)) == balBefore && address(c).balance == etherBefore);
        }
    }

    receive() external payable {}
}

